 1→/**
 2→ * AISE production-like local start (PROD-001).
 3→ *
 4→ * `bun run start` — serves the BUILT web assets plus the backend API with a
 5→ * validated, explicit configuration:
 6→ *
 7→ *   1. validates the environment in `start` mode — `AISE_DATA_DIR` is
 8→ *      REQUIRED here: a production-like start refuses to fall back to the
 9→ *      silent, cwd-dependent `./data` default (deterministic failure beats a
10→ *      silent default);
11→ *   2. requires the built web assets (`apps/web/dist/`) — run
12→ *      `bun run build` first; missing build output is a deterministic
13→ *      failure, not an implicit rebuild;
14→ *   3. starts the backend API (`bun run start` in backend/api) and serves
15→ *      `apps/web/dist` through `vite preview` with the same API proxy as
16→ *      development, so the browser needs zero configuration;
17→ *   4. one Ctrl-C tears both down.
18→ *
19→ * Honesty note: `vite preview` is Vite's local production-build server — a
20→ * production-LIKE local approximation, not a hardened internet-facing
21→ * server. The real public deployment is PROD-011 (see docs/INSTALL.md
22→ * §What-is-NOT-included).
23→ */
24→
25→import { existsSync } from "node:fs";
26→import { join, resolve } from "node:path";
27→import { spawnChild, superviseGroup } from "./lib/process-group";
28→
29→const ROOT = resolve(import.meta.dir, "..");
30→
31→function runEnvCheck(): boolean {
32→  const proc = Bun.spawnSync({
33→    cmd: [process.execPath, "tools/validate-env.ts", "--mode", "start"],
34→    cwd: ROOT,
35→    stdout: "inherit",
36→    stderr: "inherit",
37→  });
38→  return proc.exitCode === 0;
39→}
40→
41→async function main(): Promise<void> {
42→  if (!runEnvCheck()) {
43→    console.error("start: environment validation failed — refusing to start (see messages above)");
44→    process.exit(1);
45→  }
46→
47→  const distIndex = join(ROOT, "apps/web/dist/index.html");
48→  if (!existsSync(distIndex)) {
49→    console.error(
50→      "start: apps/web/dist/index.html not found — run `bun run build` first (docs/INSTALL.md §Production-like local start)",
51→    );
52→    process.exit(1);
53→  }
54→
55→  const apiHost = process.env.HOST ?? "127.0.0.1";
56→  const apiPort = process.env.PORT ?? "8080";
57→  const webPort = process.env.AISE_WEB_PORT ?? "4173";
58→  const dataDir = resolve(ROOT, process.env.AISE_DATA_DIR ?? "./data");
59→
60→  console.log(`start: web  → http://localhost:${webPort} (vite preview over apps/web/dist, proxies API routes)`);
61→  console.log(`start: api  → http://${apiHost}:${apiPort}/healthz`);
62→  console.log(`start: data → ${dataDir}`);
63→  console.log("start: press Ctrl-C once to stop both");
64→
65→  const api = spawnChild({
66→    name: "api",
67→    cmd: [process.execPath, "run", "start"],
68→    cwd: join(ROOT, "backend/api"),
69→    env: { AISE_DATA_DIR: dataDir },
70→  });
71→  const web = spawnChild({
72→    name: "web",
73→    cmd: [process.execPath, "run", "preview"],
74→    cwd: join(ROOT, "apps/web"),
75→  });
76→
77→  const code = await superviseGroup(
78→    [
79→      { name: "api", proc: api },
80→      { name: "web", proc: web },
81→    ],
82→    "start",
83→  );
84→  process.exit(code);
85→}
86→
87→void main();
