  1→/**
  2→ * AISE runtime smoke verification (PROD-001).
  3→ *
  4→ * `bun run smoke` — proves the REAL backend boots and answers, deterministically:
  5→ *
  6→ *   1. pre-flight: the fixed scratch port 8787 must be FREE — a TCP connect
  7→ *      must be refused. If anything is already listening there, the smoke
  8→ *      fails immediately instead of measuring a foreign server;
  9→ *   2. creates a scratch data directory under the OS temp dir (mkdtemp —
 10→ *      never the developer's real data dir);
 11→ *   3. starts the real API (`bun run start` in backend/api — no fixtures, no
 12→ *      in-process shortcuts) on 127.0.0.1:8787 with the scratch data dir;
 13→ *   4. waits for it to become healthy (bounded polling with child-liveness
 14→ *      checks — a child that dies, e.g. bind failure, is a deterministic
 15→ *      process-exit failure, never a timeout mystery);
 16→ *   5. asserts the live HTTP contract:
 17→ *        GET /healthz → 200, {ok:true, service:"aise-api", version:string}
 18→ *        GET /readyz  → 200, {ok:true}
 19→ *   6. ALWAYS cleans up: SIGTERM the API (SIGKILL after a bounded grace
 20→ *      period), remove the scratch data dir — and prints proof that both
 21→ *      happened;
 22→ *   7. identity proof: after the API process is stopped, the scratch port
 23→ *      must be dark. If anything still answers on 8787, the probes may have
 24→ *      hit a foreign server and the smoke FAILS — measurement causality is
 25→ *      verified, not assumed;
 26→ *   8. prints `SMOKE: PASS` / `SMOKE: FAIL` and exits 0/1 accordingly.
 27→ *
 28→ * The scratch port is fixed (8787), NOT the API default (8080): `bun run
 29→ * smoke` can run alongside `bun run dev` / `bun run start`.
 30→ */
 31→
 32→import { mkdtempSync, rmSync } from "node:fs";
 33→import { tmpdir } from "node:os";
 34→import { connect as netConnect } from "node:net";
 35→import { join, resolve } from "node:path";
 36→
 37→const ROOT = resolve(import.meta.dir, "..");
 38→const SMOKE_HOST = "127.0.0.1";
 39→const SMOKE_PORT = 8787;
 40→const HEALTH_TIMEOUT_MS = 20000;
 41→const POLL_INTERVAL_MS = 150;
 42→const SETTLE_MS = 300;
 43→const STOP_GRACE_MS = 5000;
 44→const PROBE_TIMEOUT_MS = 1000;
 45→
 46→interface Assertion {
 47→  readonly name: string;
 48→  readonly pass: boolean;
 49→  readonly detail: string;
 50→}
 51→
 52→type BootOutcome =
 53→  | { kind: "healthy" }
 54→  | { kind: "timeout"; waitedMs: number }
 55→  | { kind: "process-exit"; code: number };
 56→
 57→/**
 58→ * True when SOMETHING accepts a TCP connection on host:port. Used both as a
 59→ * pre-flight "port is free" gate and as the post-teardown identity proof.
 60→ * A connect timeout counts as "answering" (occupied) — never risk a false
 61→ * positive on an ambiguous port state.
 62→ */
 63→function portAnswers(host: string, port: number): Promise<boolean> {
 64→  return new Promise((resolve) => {
 65→    const socket = netConnect({ host, port });
 66→    let settled = false;
 67→    const finish = (result: boolean): void => {
 68→      if (!settled) {
 69→        settled = true;
 70→        socket.destroy();
 71→        resolve(result);
 72→      }
 73→    };
 74→    socket.setTimeout(PROBE_TIMEOUT_MS, () => {
 75→      finish(true);
 76→    });
 77→    socket.once("connect", () => {
 78→      finish(true);
 79→    });
 80→    socket.once("error", () => {
 81→      finish(false);
 82→    });
 83→  });
 84→}
 85→
 86→function isRecord(value: unknown): value is Record<string, unknown> {
 87→  return typeof value === "object" && value !== null;
 88→}
 89→
 90→async function fetchJson(path: string): Promise<{ status: number; body: unknown }> {
 91→  const response = await fetch(`http://${SMOKE_HOST}:${SMOKE_PORT}${path}`, {
 92→    // Bounded per-request timeout so a wedged server cannot hang the smoke.
 93→    signal: AbortSignal.timeout(2000),
 94→  });
 95→  let body: unknown;
 96→  try {
 97→    body = await response.json();
 98→  } catch {
 99→    body = undefined;
100→  }
101→  return { status: response.status, body };
102→}
103→
104→function pending(ms: number): Promise<"pending"> {
105→  return new Promise((resolve) => {
106→    setTimeout(() => {
107→      resolve("pending");
108→    }, ms).unref();
109→  });
110→}
111→
112→async function waitForBoot(proc: Bun.Subprocess): Promise<BootOutcome> {
113→  const start = Date.now();
114→  const deadline = start + HEALTH_TIMEOUT_MS;
115→  const exitPromise = proc.exited.then((code) => ({ kind: "process-exit" as const, code }));
116→  for (;;) {
117→    try {
118→      const { status } = await fetchJson("/healthz");
119→      if (status === 200) {
120→        // A 200 alone does not prove OUR child is the listener. The child
121→        // must be alive now AND after a settle window (bind failures such as
122→        // EADDRINUSE kill the process at construction time, well inside the
123→        // window). The post-teardown identity proof closes the residual gap.
124→        if (proc.exitCode !== null) {
125→          return { kind: "process-exit", code: proc.exitCode };
126→        }
127→        const settle = await Promise.race([exitPromise, pending(SETTLE_MS)]);
128→        if (settle !== "pending") {
129→          return settle;
130→        }
131→        if (proc.exitCode !== null) {
132→          return { kind: "process-exit", code: proc.exitCode };
133→        }
134→        return { kind: "healthy" };
135→      }
136→    } catch {
137→      // Not up yet (connection refused / not listening) — keep polling.
138→    }
139→    if (Date.now() >= deadline) {
140→      return { kind: "timeout", waitedMs: Date.now() - start };
141→    }
142→    const exited = await Promise.race([exitPromise, pending(POLL_INTERVAL_MS)]);
143→    if (exited !== "pending") {
144→      return exited;
145→    }
146→  }
147→}
148→
149→async function stopApi(proc: Bun.Subprocess): Promise<number> {
150→  if (proc.exitCode !== null) {
151→    return proc.exitCode;
152→  }
153→  proc.kill("SIGTERM");
154→  const exited = await Promise.race([proc.exited, pending(STOP_GRACE_MS).then(() => "timeout" as const)]);
155→  if (exited === "timeout" && proc.exitCode === null) {
156→    proc.kill("SIGKILL");
157→    return await proc.exited;
158→  }
159→  return exited === "timeout" ? (proc.exitCode ?? 1) : exited;
160→}
161→
162→async function main(): Promise<void> {
163→  const failures: string[] = [];
164→
165→  // Pre-flight: the scratch port must be free, otherwise the smoke would
166→  // measure whatever server already holds it.
167→  if (await portAnswers(SMOKE_HOST, SMOKE_PORT)) {
168→    console.error(
169→      `  FAIL  pre-flight — port ${SMOKE_PORT} is already in use by another process; stop it and re-run bun run smoke`,
170→    );
171→    failures.push(`port ${SMOKE_PORT} already in use before the smoke started`);
172→    console.log("SMOKE: FAIL");
173→    process.exit(1);
174→  }
175→
176→  const dataDir = mkdtempSync(join(tmpdir(), "aise-smoke-"));
177→  console.log(`smoke: scratch data dir ${dataDir}`);
178→  console.log(`smoke: starting backend/api on http://${SMOKE_HOST}:${SMOKE_PORT} (real process, no fixtures)`);
179→
180→  const api = Bun.spawn({
181→    cmd: [process.execPath, "run", "start"],
182→    cwd: join(ROOT, "backend/api"),
183→    env: {
184→      ...process.env,
185→      HOST: SMOKE_HOST,
186→      PORT: String(SMOKE_PORT),
187→      AISE_DATA_DIR: dataDir,
188→      LOG_LEVEL: "info",
189→    },
190→    stdout: "inherit",
191→    stderr: "inherit",
192→  });
193→
194→  const assertions: Assertion[] = [];
195→  let bootFailure: string | null = null;
196→
197→  const boot = await waitForBoot(api);
198→  if (boot.kind === "healthy") {
199→    const health = await fetchJson("/healthz");
200→    const healthBody = isRecord(health.body) ? health.body : {};
201→    assertions.push(
202→      {
203→        name: "GET /healthz → HTTP 200",
204→        pass: health.status === 200,
205→        detail: `status ${health.status}`,
206→      },
207→      {
208→        name: "GET /healthz body ok === true",
209→        pass: healthBody["ok"] === true,
210→        detail: `ok = ${String(healthBody["ok"])}`,
211→      },
212→      {
213→        name: "GET /healthz body service === \"aise-api\"",
214→        pass: healthBody["service"] === "aise-api",
215→        detail: `service = ${String(healthBody["service"])}`,
216→      },
217→      {
218→        name: "GET /healthz body version is a non-empty string",
219→        pass:
220→          typeof healthBody["version"] === "string" && (healthBody["version"] as string).length > 0,
221→        detail: `version = ${String(healthBody["version"])}`,
222→      },
223→    );
224→
225→    const ready = await fetchJson("/readyz");
226→    const readyBody = isRecord(ready.body) ? ready.body : {};
227→    assertions.push(
228→      {
229→        name: "GET /readyz → HTTP 200",
230→        pass: ready.status === 200,
231→        detail: `status ${ready.status}`,
232→      },
233→      {
234→        name: "GET /readyz body ok === true",
235→        pass: readyBody["ok"] === true,
236→        detail: `ok = ${String(readyBody["ok"])}`,
237→      },
238→    );
239→
240→    // The API process must still be alive after the assertions — a process
241→    // that died mid-smoke invalidates the measurement.
242→    if (api.exitCode !== null) {
243→      bootFailure = `API process exited (code ${api.exitCode}) during the smoke assertions`;
244→    }
245→  } else if (boot.kind === "timeout") {
246→    bootFailure = `API did not become healthy within ${HEALTH_TIMEOUT_MS} ms on port ${SMOKE_PORT}`;
247→  } else {
248→    bootFailure = `API process exited (code ${boot.code}) before becoming healthy — port ${SMOKE_PORT} in use or startup failure; see API output above`;
249→  }
250→
251→  // Cleanup ALWAYS runs, even after failed boot/assertions.
252→  const apiExit = await stopApi(api);
253→  console.log(`smoke: api stopped (exit code ${apiExit})`);
254→  rmSync(dataDir, { recursive: true, force: true });
255→  console.log(`smoke: scratch data dir removed (${dataDir})`);
256→
257→  // Identity proof: the server we just stopped was the one answering. If
258→  // anything still accepts connections on the scratch port, the probes may
259→  // have hit a foreign server — refuse to report a false positive.
260→  if (await portAnswers(SMOKE_HOST, SMOKE_PORT)) {
261→    bootFailure =
262→      bootFailure ??
263→      "another server is still answering on the scratch port after the smoke's API process stopped — the smoke probes may have hit a foreign process";
264→  }
265→
266→  for (const assertion of assertions) {
267→    const line = `  ${assertion.pass ? "pass" : "FAIL"}  ${assertion.name} — ${assertion.detail}`;
268→    if (assertion.pass) {
269→      console.log(line);
270→    } else {
271→      console.error(line);
272→    }
273→  }
274→  if (bootFailure !== null) {
275→    console.error(`  FAIL  boot — ${bootFailure}`);
276→  }
277→
278→  const pass = bootFailure === null && assertions.length > 0 && assertions.every((a) => a.pass);
279→  console.log(pass ? "SMOKE: PASS" : "SMOKE: FAIL");
280→  process.exit(pass ? 0 : 1);
281→}
282→
283→void main();
