 1→/**
 2→ * AISE environment validation CLI (PROD-001).
 3→ *
 4→ * Validates the live environment (Bun automatically loads a root `.env` file
 5→ * into `process.env` before this runs) against the declared schema in
 6→ * `tools/env-schema.ts` and exits deterministically:
 7→ *
 8→ *   - exit 0 + `ENV: PASS`  — every declared variable is valid; optional
 9→ *     provider credentials that are unset are reported as `disabled (optional)`;
10→ *   - exit 1 + `ENV: FAIL`  — every missing-required / malformed variable is
11→ *     listed with a precise, actionable message (never the value).
12→ *
13→ * Usage:
14→ *   bun run check:env                    # dev mode
15→ *   bun tools/validate-env.ts --mode start
16→ *
17→ * The root `dev` and `start` orchestrators invoke this before launching any
18→ * child process, so a broken environment can never produce a half-started
19→ * runtime.
20→ */
21→
22→import { evaluateEnv, VALIDATION_MODES, type EnvCheck, type ValidationMode } from "./env-schema";
23→
24→function parseMode(argv: readonly string[]): ValidationMode | null {
25→  // Accept both `--mode start` and `--mode=start`.
26→  const inline = argv.find((arg) => arg.startsWith("--mode="));
27→  if (inline !== undefined) {
28→    const value = inline.slice("--mode=".length);
29→    return (VALIDATION_MODES as readonly string[]).includes(value)
30→      ? (value as ValidationMode)
31→      : null;
32→  }
33→  const flagIndex = argv.indexOf("--mode");
34→  if (flagIndex !== -1) {
35→    const value = argv[flagIndex + 1];
36→    if (value === undefined) {
37→      return null;
38→    }
39→    return (VALIDATION_MODES as readonly string[]).includes(value)
40→      ? (value as ValidationMode)
41→      : null;
42→  }
43→  return "dev";
44→}
45→
46→function main(): void {
47→  const mode = parseMode(process.argv.slice(2));
48→  if (mode === null) {
49→    console.error(
50→      `usage: bun tools/validate-env.ts [--mode ${VALIDATION_MODES.join("|")}]`,
51→    );
52→    process.exit(2);
53→  }
54→
55→  const report = evaluateEnv(process.env, mode);
56→  const nameWidth = Math.max(...report.checks.map((check) => check.name.length));
57→  const statusLabels: Record<EnvCheck["status"], string> = {
58→    ok: "ok",
59→    "ok-default": "ok",
60→    "enabled-optional": "ok",
61→    "disabled-optional": "disabled (optional)",
62→    missing: "MISSING",
63→    invalid: "INVALID",
64→  };
65→
66→  console.log(`AISE environment validation (mode: ${mode})`);
67→  for (const check of report.checks) {
68→    const label = statusLabels[check.status];
69→    const shownDetail = check.detail === label ? "" : check.detail;
70→    const padding = " ".repeat(Math.max(1, nameWidth - check.name.length) + 2);
71→    const line = `  ${check.name}${padding}${label.padEnd(20)}${shownDetail}`;
72→    console.log(line.trimEnd());
73→  }
74→
75→  if (!report.ok) {
76→    console.log("ENV: FAIL");
77→    console.log("Fix the following, then re-run `bun run check:env` (docs/INSTALL.md §Environment):");
78→    for (const issue of report.issues) {
79→      console.error(`  - ${issue}`);
80→    }
81→    process.exit(1);
82→  }
83→  console.log("ENV: PASS");
84→}
85→
86→main();
87→

 1→/**
 2→ * AISE root build (PROD-001; serverless bundle added by PROD-011).
 3→ *
 4→ * `bun run build` — builds every workspace artifact needed by the
 5→ * production-like local start (`bun run start`) AND by the Vercel
 6→ * deployment (vercel.json `buildCommand` runs this same script):
 7→ *
 8→ *   - apps/web: `vite build` → `apps/web/dist` (the served web bundle);
 9→ *   - backend/api: no build artifact for the local runtime — the API runs
10→ *     its TypeScript sources directly through Bun (`bun run src/main.ts`),
11→ *     which is the documented runtime contract;
12→ *   - api/[...path].mjs: the ONE catch-all Vercel serverless function —
13→ *     COMMITTED as a deploy beacon (Vercel's zero-config/functions scan
14→ *     needs the file PRE-build; a gitignored artifact only worked when a
15→ *     restored build cache happened to pre-seed it — the 2026-09-20
16→ *     lesson). Every build regenerates the bundle deterministically, so
17→ *     the committed bytes are always refreshed from tracked sources;
18→ *     esbuild-bundled from `api/_serverless.ts` into a self-contained ESM
19→ *     bundle for the Node.js runtime (the repo's Bun-style extensionless
20→ *     TS imports cannot go through @vercel/node's checker; the pre-bundled
21→ *     .mjs needs no tracing, no TS check and no node_modules at runtime).
22→ *     The catch-all FILE NAME `[...path]` is Vercel's zero-config REQUIRED
23→ *     catch-all convention — the route matches EVERY depth under /api/.
24→ *     (The `[[...path]]` OPTIONAL catch-all spelling is a Next.js convention
25→ *     the raw function builder does not understand: a real deployment
26→ *     proved it compiles to a SINGLE-segment route `^/api/([^/]+)$`, which
27→ *     404s every multi-segment path like /api/v1/gaps.) The source file's
28→ *     leading underscore (`api/_serverless.ts`) keeps Vercel's zero-config
29→ *     from picking the TS source up as a second, traced, broken function.
30→ *
31→ * Deterministic postcondition: the command fails (exit 1, `BUILD: FAIL`) if
32→ * any build exits non-zero OR an expected artifact (`apps/web/dist/index.html`,
33→ * `api/[...path].mjs`) is missing afterwards — a build that "succeeds"
34→ * without producing its artifacts is a failure, not a silent success.
35→ */
36→
37→import { existsSync } from "node:fs";
38→import { join, relative, resolve } from "node:path";
39→import * as esbuild from "esbuild";
40→
41→const ROOT = resolve(import.meta.dir, "..");
42→
43→async function main(): Promise<void> {
44→  const distIndex = join(ROOT, "apps/web/dist/index.html");
45→
46→  console.log("build: apps/web (vite build)");
47→  const proc = Bun.spawnSync({
48→    cmd: [process.execPath, "run", "build"],
49→    cwd: join(ROOT, "apps/web"),
50→    stdout: "inherit",
51→    stderr: "inherit",
52→  });
53→  if (proc.exitCode !== 0) {
54→    console.error(`BUILD: FAIL — apps/web build exited with code ${proc.exitCode ?? 1}`);
55→    process.exit(1);
56→  }
57→  if (!existsSync(distIndex)) {
58→    console.error("BUILD: FAIL — apps/web/dist/index.html missing after build");
59→    process.exit(1);
60→  }
61→
62→  const serverlessSource = join(ROOT, "api", "_serverless.ts");
63→  const serverlessBundle = join(ROOT, "api", "[...path].mjs");
64→  console.log("build: api/[...path].mjs (esbuild bundle of api/_serverless.ts)");
65→  const bundle = existsSync(serverlessSource)
66→    ? await esbuild.build({
67→        entryPoints: [serverlessSource],
68→        outfile: serverlessBundle,
69→        bundle: true,
70→        platform: "node",
71→        format: "esm",
72→        target: "node22",
73→        legalComments: "none",
74→        banner: {
75→          js:
76→            "/* AISE serverless catch-all — generated by tools/build.ts from api/_serverless.ts; DO NOT EDIT (committed deploy beacon, regenerated deterministically by every build). */",
77→        },
78→      })
79→    : null;
80→  if (bundle === null || bundle.errors.length > 0 || !existsSync(serverlessBundle)) {
81→    console.error("BUILD: FAIL — api/[...path].mjs bundle failed or missing after build");
82→    process.exit(1);
83→  }
84→
85→  console.log(`BUILD: PASS (${relative(ROOT, distIndex)}, ${relative(ROOT, serverlessBundle)})`);
86→}
87→
88→await main();
89→

 1→/**
 2→ * Root `bun run db:migrate` (PROD-005) — thin, offline-safe shim.
 3→ *
 4→ * Applies the pending Postgres schema migrations on the database named by
 5→ * DATABASE_URL (ordered, versioned, idempotent — see
 6→ * backend/api/src/pg/migrate.ts). The shim pre-checks DATABASE_URL and
 7→ * fails CLEANLY with an actionable message when it is missing, without
 8→ * spawning anything; the actual runner is backend/api/src/pg/cli.ts
 9→ * (spawned in backend/api so workspace dependencies resolve there).
10→ *
11→ * Without DATABASE_URL the app runs in local FS mode and needs no
12→ * migrations — this script existing is never a reason to require a
13→ * database (docs/INSTALL.md §Persistence).
14→ */
15→
16→import { join, resolve } from "node:path";
17→
18→const ROOT = resolve(import.meta.dir, "..");
19→
20→function databaseUrl(): string | null {
21→  const raw = process.env["DATABASE_URL"]?.trim();
22→  return raw === undefined || raw === "" ? null : raw;
23→}
24→
25→const url = databaseUrl();
26→if (url === null) {
27→  console.error(
28→    "db:migrate: DATABASE_URL is not set — nothing to migrate.\n" +
