  1→/**
  2→ * Managed child-process group for the AISE root orchestrators (PROD-001).
  3→ *
  4→ * Bun-native orchestration — no external `concurrently`-style dependency:
  5→ *
  6→ * - `spawnChild` starts a child with inherited stdio so its output streams
  7→ *   straight into the operator's terminal;
  8→ * - `superviseGroup` keeps the group running until either (a) the parent
  9→ *   receives SIGINT/SIGTERM — then every child is stopped (SIGTERM, with a
 10→ *   SIGKILL fallback after a bounded timeout) and the supervisor exits 0 —
 11→ *   or (b) a child exits on its own — then the remaining children are torn
 12→ *   down and the supervisor exits with that child's exit code. One Ctrl-C
 13→ *   tears the whole runtime down; a crashing component never leaves a
 14→ *   half-running group behind.
 15→ */
 16→
 17→export interface SpawnSpec {
 18→  /** Short name used in lifecycle log lines. */
 19→  readonly name: string;
 20→  readonly cmd: readonly string[];
 21→  readonly cwd: string;
 22→  /** Extra environment merged over the parent environment. */
 23→  readonly env?: Readonly<Record<string, string>>;
 24→}
 25→
 26→export function spawnChild(spec: SpawnSpec): Bun.Subprocess {
 27→  return Bun.spawn({
 28→    cmd: [...spec.cmd],
 29→    cwd: spec.cwd,
 30→    env: spec.env === undefined ? process.env : { ...process.env, ...spec.env },
 31→    stdout: "inherit",
 32→    stderr: "inherit",
 33→  });
 34→}
 35→
 36→export interface ManagedChild {
 37→  readonly name: string;
 38→  readonly proc: Bun.Subprocess;
 39→}
 40→
 41→export interface SuperviseOptions {
 42→  /** How long to wait after SIGTERM before escalating to SIGKILL. */
 43→  readonly stopTimeoutMs?: number;
 44→}
 45→
 46→const STOP_TIMEOUT_MS_DEFAULT = 5000;
 47→
 48→const TIMEOUT = Symbol("timeout");
 49→
 50→function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T | typeof TIMEOUT> {
 51→  return Promise.race([
 52→    promise,
 53→    new Promise<typeof TIMEOUT>((resolve) => {
 54→      setTimeout(() => {
 55→        resolve(TIMEOUT);
 56→      }, ms).unref();
 57→    }),
 58→  ]);
 59→}
 60→
 61→async function stopChild(child: ManagedChild, stopTimeoutMs: number): Promise<void> {
 62→  if (child.proc.exitCode !== null) {
 63→    return;
 64→  }
 65→  child.proc.kill("SIGTERM");
 66→  const exited = await withTimeout(child.proc.exited, stopTimeoutMs);
 67→  if (exited === TIMEOUT && child.proc.exitCode === null) {
 68→    child.proc.kill("SIGKILL");
 69→    await child.proc.exited;
 70→  }
 71→}
 72→
 73→async function teardown(children: readonly ManagedChild[], stopTimeoutMs: number): Promise<void> {
 74→  // Signal first, then wait — so slow children get their full grace period in
 75→  // parallel instead of sequentially after each sibling.
 76→  for (const child of children) {
 77→    if (child.proc.exitCode === null) {
 78→      child.proc.kill("SIGTERM");
 79→    }
 80→  }
 81→  for (const child of children) {
 82→    await stopChild(child, stopTimeoutMs);
 83→  }
 84→}
 85→
 86→function waitForFirstExit(
 87→  children: readonly ManagedChild[],
 88→): Promise<{ name: string; code: number | null }> {
 89→  return new Promise((resolve) => {
 90→    for (const child of children) {
 91→      void child.proc.exited.then((code) => {
 92→        resolve({ name: child.name, code });
 93→      });
 94→    }
 95→  });
 96→}
 97→
 98→/**
 99→ * Run until the group exits. Resolves with the process exit code the
100→ * orchestrator should propagate:
101→ *
102→ * - signal teardown (Ctrl-C) → 0;
103→ * - first child exit → that child's exit code (1 when it died from a signal).
104→ */
105→export async function superviseGroup(
106→  children: readonly ManagedChild[],
107→  label: string,
108→  options: SuperviseOptions = {},
109→): Promise<number> {
110→  const stopTimeoutMs = options.stopTimeoutMs ?? STOP_TIMEOUT_MS_DEFAULT;
111→
112→  const signalPromise = new Promise<string>((resolve) => {
113→    process.on("SIGINT", () => {
114→      resolve("SIGINT");
115→    });
116→    process.on("SIGTERM", () => {
117→      resolve("SIGTERM");
118→    });
119→  });
120→
121→  const exitPromise = waitForFirstExit(children);
122→
123→  const event = await Promise.race([
124→    signalPromise.then((signal) => ({ kind: "signal" as const, signal })),
125→    exitPromise.then((exit) => ({ kind: "exit" as const, exit })),
126→  ]);
127→
128→  if (event.kind === "signal") {
129→    console.log(`${label}: received ${event.signal} — stopping ${children.map((c) => c.name).join(" and ")}`);
130→    await teardown(children, stopTimeoutMs);
131→    console.log(`${label}: stopped`);
132→    return 0;
133→  }
134→
135→  const { name, code } = event.exit;
136→  const exitCode = code ?? 1;
137→  console.error(`${label}: ${name} exited with code ${exitCode} — stopping the rest`);
138→  await teardown(
139→    children.filter((child) => child.proc.exitCode === null),
140→    stopTimeoutMs,
141→  );
142→  return exitCode;
143→}
