/** Format a route into its canonical hash text (round-trips `parseHash`). */
export function formatRoute(route: Route): string {
  switch (route.name) {
    case "dashboard":
      return "#/";
    case "projects":
      return "#/projects";
    case "project":
      return `#/projects/${encodeURIComponent(route.projectId)}`;
    case "sitetwin":
      return `#/projects/${encodeURIComponent(route.projectId)}/sitetwin`;
    case "boq-lens":
      return `#/projects/${encodeURIComponent(route.projectId)}/boq-lens`;
    case "case":
      return `#/projects/${encodeURIComponent(route.projectId)}/case`;
    case "outcomes":
      return `#/projects/${encodeURIComponent(route.projectId)}/outcomes`;
    case "intervention": {
      const base = `#/projects/${encodeURIComponent(route.projectId)}/intervention`;
      const params: string[] = [];
      if (route.query.layer !== undefined) {
        params.push(`layer=${String(route.query.layer)}`);
      }
      if (route.query.scenario !== undefined) {
        params.push(`scenario=${encodeURIComponent(route.query.scenario)}`);
      }
      return params.length === 0 ? base : `${base}?${params.join("&")}`;
    }
    case "solution": {
      const base = `#/projects/${encodeURIComponent(route.projectId)}/solution`;
      const params: string[] = [];
      if (route.query.case !== undefined) {
        params.push(`case=${encodeURIComponent(route.query.case)}`);
      }
      if (route.query.boqLine !== undefined) {
        params.push(`boq-line=${encodeURIComponent(route.query.boqLine)}`);
      }
      if (route.query.step !== undefined) {
        params.push(`step=${String(route.query.step)}`);
      }
      return params.length === 0 ? base : `${base}?${params.join("&")}`;
    }
    case "settings":
      return "#/settings";
    case "not-found":
      return route.hash;
  }
}
