import { spawn } from "node:child_process";
import { existsSync, mkdirSync, openSync, readFileSync, rmSync, writeFileSync, type Dirent } from "node:fs";
import { randomBytes } from "node:crypto";
import { connect as netConnect } from "node:net";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(import.meta.dir, "..");

/* ------------------------------------------------------------------ */
/* Public surface (consumed by tools/bootstrap.test.ts — deterministic */
/* tests inject fakes for every effect; nothing here touches the        */
/* network, ports or processes on its own).                            */
/* ------------------------------------------------------------------ */

/** One phase command the orchestrator delegates to a tool by subprocess. */
export interface CommandSpec {
  readonly cmd: readonly string[];
  readonly cwd: string;
  /** Extra environment merged over the parent environment. */
  readonly env?: Readonly<Record<string, string>>;
}

/** The captured outcome of one delegated command. */
export interface CommandResult {
  readonly exitCode: number;
  readonly stdout: string;
  readonly stderr: string;
}

/** A background (supervised) process started by the start phase. */
export interface BackgroundHandle {
  readonly pid: number;
  /** Best-effort teardown: SIGTERM, bounded wait, SIGKILL fallback. */
  stop(): Promise<void>;
}

/** Everything with an effect the orchestrator needs, injectable for tests. */
export interface BootstrapDeps {
  /** Run one phase command to completion, capturing combined output. */
  runCommand(spec: CommandSpec): Promise<CommandResult>;
  /** Start the supervised background server; its output goes to logPath. */
  startBackground(spec: CommandSpec, logPath: string): Promise<BackgroundHandle>;
  /** True when something accepts a TCP connection on host:port. */
  portAnswers(host: string, port: number): Promise<boolean>;
  /** GET a URL as text; null when the request fails (any reason). */
  fetchText(url: string): Promise<string | null>;
  /** Sleep ms (tests inject a no-op). */
  sleep(ms: number): Promise<void>;
  /** Filesystem facade over the demo state paths (all under the repo). */
  fs: {
    exists(path: string): boolean;
    readFile(path: string): string | null;
    writeFile(path: string, content: string): void;
    removeDir(path: string): void;
    mkdirs(path: string): void;
    /** Directory entries of a path (empty when absent). */
    list(path: string): readonly string[];
  };
  /** Current process environment (Bun already merged the root .env). */
  env: Record<string, string | undefined>;
  /** Printers (banner/log/fail lines — asserted by tests). */
  log(line: string): void;
  fail(line: string): void;
  /** Exit code setter for the embedding process (main uses process.exit). */
  exit(code: number): void;
}

/** The phases, in execution order. */
export const PHASES = [
  "prerequisites",
  "install",
  "env",
  "migrate",
  "seed",
  "build",
  "start",
  "smoke",
] as const;

export type PhaseName = (typeof PHASES)[number];

/** The persisted bootstrap state (data/demo/.bootstrap-state.json). */
export interface BootstrapState {
  readonly schemaVersion: 1;
  readonly completedPhases: readonly PhaseName[];
  /** The generated throwaway demo AUTH_SECRET (reused across re-runs). */
  readonly authSecret: string;
  readonly server:
    | {
        readonly pid: number;
        readonly logPath: string;
        readonly apiPort: number;
        readonly webPort: number;
        readonly apiHost: string;
      }
    | null;
}

export interface BootstrapOptions {
  /** Tear down demo state and re-run from zero. */
  readonly fresh: boolean;
}

export interface BootstrapOutcome {
  /** The phase that failed (null when the bootstrap succeeded). */
  readonly failedPhase: PhaseName | null;
  /** Pids/background handles started by THIS run (torn down on failure). */
  readonly exitCode: number;
}

/* ------------------------------------------------------------------ */
/* Derived configuration                                               */
/* ------------------------------------------------------------------ */

export interface DemoConfig {
  readonly dataDir: string;
  readonly statePath: string;
  readonly serverLogPath: string;
  readonly apiHost: string;
  readonly apiPort: number;
  readonly webPort: number;
  readonly smokePort: number;
  readonly webAppUrl: string;
  readonly demoPathUrl: string;
  readonly apiHealthUrl: string;
  readonly guidePath: string;
  /** The demo-safe environment overlay (fill-only-missing). */
  readonly envOverlay: Readonly<Record<string, string>>;
  /** True when DATABASE_URL is set (Postgres mode → migrate/seed run). */
  readonly databaseMode: boolean;
}

/**
 * Derive the demo configuration from the environment. Fill-only-missing:
 * values the evaluator already set (shell or root `.env` — Bun merged both
 * into `env`) pass through untouched; only absent ones get demo defaults.
 */
export function deriveDemoConfig(
  env: Record<string, string | undefined>,
  authSecret: string,
): DemoConfig {
  const dataDir = resolve(ROOT, env["AISE_DATA_DIR"] ?? "data/demo");
  const apiPort = parsePort(env["PORT"], 8080);
  const webPort = parsePort(env["AISE_WEB_PORT"], 4173);
  const apiHost = env["HOST"] ?? "127.0.0.1";
  const overlay: Record<string, string> = {
    AISE_DATA_DIR: dataDir,
    AISE_AUTH: env["AISE_AUTH"] ?? "1",
  };
  if (env["AUTH_SECRET"] === undefined) {
    overlay["AUTH_SECRET"] = authSecret;
  }
  const databaseUrl = env["DATABASE_URL"]?.trim();
  return {
    dataDir,
    statePath: join(dataDir, ".bootstrap-state.json"),
    serverLogPath: join(dataDir, "server.log"),
    apiHost,
    apiPort,
    webPort,
    smokePort: 8787,
    webAppUrl: `http://localhost:${webPort}/`,
    demoPathUrl: `http://localhost:${webPort}/#/projects`,
    apiHealthUrl: `http://${apiHost === "0.0.0.0" ? "127.0.0.1" : apiHost}:${apiPort}/healthz`,
    guidePath: "docs/EVALUATOR-GUIDE.md",
    envOverlay: overlay,
    databaseMode: databaseUrl !== undefined && databaseUrl !== "",
  };
}

function parsePort(raw: string | undefined, fallback: number): number {
  if (raw === undefined || raw.trim() === "") {
    return fallback;
  }
  const port = Number.parseInt(raw, 10);
  return Number.isInteger(port) && port >= 1 && port <= 65535 ? port : fallback;
}

/**
 * Read the persisted state (null when absent or unreadable — a corrupt
 * state file never blocks the demo; it is treated as "not bootstrapped").
 */
export function readState(fs: BootstrapDeps["fs"], path: string): BootstrapState | null {
  if (!fs.exists(path)) {
    return null;
  }
  try {
    const raw = fs.readFile(path);
    if (raw === null) {
      return null;
    }
    const parsed = JSON.parse(raw) as Partial<BootstrapState>;
    if (parsed.schemaVersion !== 1 || typeof parsed.authSecret !== "string") {
      return null;
    }
    return {
      schemaVersion: 1,
      completedPhases: Array.isArray(parsed.completedPhases)
        ? (parsed.completedPhases.filter((p) => (PHASES as readonly string[]).includes(p)) as PhaseName[])
        : [],
      authSecret: parsed.authSecret,
      server:
        parsed.server !== null &&
        typeof parsed.server === "object" &&
        typeof parsed.server.pid === "number" &&
        typeof parsed.server.logPath === "string" &&
        typeof parsed.server.apiPort === "number" &&
        typeof parsed.server.webPort === "number" &&
        typeof parsed.server.apiHost === "string"
          ? {
              pid: parsed.server.pid,
              logPath: parsed.server.logPath,
              apiPort: parsed.server.apiPort,
              webPort: parsed.server.webPort,
              apiHost: parsed.server.apiHost,
            }
          : null,
    };
  } catch {
    return null;
  }
}

/** The tool output tail printed on failure (bounded, actionable). */
export function outputTail(text: string, maxLines = 40): string {
  const lines = text.trimEnd().split("\n");
  if (lines.length <= maxLines) {
    return text.trimEnd();
  }
  return `[... ${lines.length - maxLines} earlier line(s) elided]\n${lines.slice(-maxLines).join("\n")}`;
}

/* ------------------------------------------------------------------ */
/* The orchestrator                                                     */
/* ------------------------------------------------------------------ */

interface PhaseContext {
  readonly deps: BootstrapDeps;
  readonly config: DemoConfig;
  readonly state: BootstrapState | null;
  /** Phases completed by THIS run (written to state incrementally). */
  completed: PhaseName[];
  /** The background server handle started by THIS run (failure teardown). */
  background: BackgroundHandle | null;
  /** The state mutated as phases complete (persisted by persistState). */
  mutable: {
    authSecret: string;
    server: BootstrapState["server"];
  };
}

function failPhase(ctx: PhaseContext, phase: PhaseName, detail: string): never {
  ctx.deps.fail("");
  ctx.deps.fail(`demo: FAILED at phase "${phase}"`);
  for (const line of detail.split("\n")) {
    ctx.deps.fail(`  ${line}`);
  }
  ctx.deps.fail("");
  ctx.deps.fail("  troubleshooting:");
  ctx.deps.fail("  - docs/EVALUATOR-GUIDE.md §5 (Troubleshooting) — the demo's top-failure table");
  ctx.deps.fail("  - docs/INSTALL.md §11 (Troubleshooting) — the authoritative install guide");
  void teardownBackground(ctx);
  ctx.deps.exit(1);
  throw new Error(`unreachable: exit hook did not exit (phase ${phase})`);
}

async function teardownBackground(ctx: PhaseContext): Promise<void> {
  if (ctx.background !== null) {
    ctx.deps.log("demo: cleanup — stopping the server this run started (no half-started runtime)");
    await ctx.background.stop();
    ctx.background = null;
    ctx.mutable.server = null;
  }
}

function persistState(ctx: PhaseContext): void {
  const state: BootstrapState = {
    schemaVersion: 1,
    completedPhases: ctx.completed,
    authSecret: ctx.mutable.authSecret,
    server: ctx.mutable.server,
  };
  try {
    ctx.deps.fs.mkdirs(dirname(ctx.config.statePath));
    ctx.deps.fs.writeFile(ctx.config.statePath, `${JSON.stringify(state, null, 2)}\n`);
  } catch (error) {
    // The state file is an idempotency HINT, never a gate: a write failure
    // is reported but never fails the demo.
    ctx.deps.fail(`demo: note — could not persist the bootstrap state file (${String(error)})`);
  }
}

function phaseBanner(ctx: PhaseContext, index: number, name: PhaseName): void {
  ctx.deps.log("");
  ctx.deps.log(`==> demo: phase ${index + 1}/${PHASES.length} — ${name}`);
}

function phaseDone(ctx: PhaseContext, name: PhaseName, note: string): void {
  ctx.deps.log(`    ${name}: ${note}`);
}

/** Phase 1 — prerequisites. */
async function phasePrerequisites(ctx: PhaseContext): Promise<void> {
  const { deps, config } = ctx;

  // Bun ≥ 1.2 (docs/INSTALL.md §1 — the single runtime/toolchain).
  const version = await deps.runCommand({ cmd: [process.execPath, "--version"], cwd: ROOT });
  const versionText = `${version.stdout}${version.stderr}`.trim();
  const match = /(\d+)\.(\d+)/.exec(versionText);
  if (version.exitCode !== 0 || match === null) {
    failPhase(
      ctx,
      "prerequisites",
      `Bun is not runnable (${versionText || `exit code ${version.exitCode}`}).\n` +
        "  Install Bun ≥ 1.2 — https://bun.sh/docs/install — then re-run `bun run demo`.",
    );
  }
  const [, majorRaw, minorRaw] = match;
  const major = Number.parseInt(majorRaw ?? "0", 10);
  const minor = Number.parseInt(minorRaw ?? "0", 10);
  if (major < 1 || (major === 1 && minor < 2)) {
    failPhase(
      ctx,
      "prerequisites",
      `Bun ${versionText} is too old — AISE requires Bun ≥ 1.2 (docs/INSTALL.md §1).\n` +
        "  Upgrade: https://bun.sh/docs/install",
    );
  }
  phaseDone(ctx, "prerequisites", `bun ${versionText} (≥ 1.2)`);

  // Ports: free, or held by the demo's OWN already-running server.
  const ours = await demoServerAlreadyUp(ctx);
  if (ours !== null) {
    phaseDone(
      ctx,
      "prerequisites",
      `ports ${config.apiPort}/${config.webPort} are held by the running demo server (pid ${ours}) — idempotent re-run`,
    );
    return;
  }
  for (const [label, host, port] of [
    ["API", config.apiHost === "0.0.0.0" ? "127.0.0.1" : config.apiHost, config.apiPort],
    ["web", "localhost", config.webPort],
    ["smoke scratch", "127.0.0.1", config.smokePort],
  ] as const) {
    if (await deps.portAnswers(host, port)) {
      failPhase(
        ctx,
        "prerequisites",
        `port ${port} (${label}) is already in use by another process.\n` +
          "  Stop that process, or change the port in your root .env\n" +
          "  (PORT for the API, AISE_WEB_PORT for the web app — docs/INSTALL.md §10 Ports and URLs).\n" +
          `  The smoke scratch port ${config.smokePort} is fixed (docs/INSTALL.md §8).`,
      );
    }
  }
  phaseDone(ctx, "prerequisites", `ports ${config.apiPort} (API), ${config.webPort} (web), ${config.smokePort} (smoke) are free`);
}

/**
 * True (pid) when the demo's own server is already answering: the state
 * file records a live pid AND the API port answers /healthz as aise-api.
 * Never guesses: an unknown holder of the port is a prerequisite failure.
 */
async function demoServerAlreadyUp(ctx: PhaseContext): Promise<number | null> {
  const { deps, config, state } = ctx;
  if (state === null || state.server === null) {
    return null;
  }
  if (state.server.apiPort !== config.apiPort || state.server.webPort !== config.webPort) {
    return null;
  }
  const health = await deps.fetchText(config.apiHealthUrl);
  if (health === null || !health.includes('"service":"aise-api"') || !health.includes('"ok":true')) {
    return null;
  }
  return state.server.pid;
}

/** Phase 2 — install. */
async function phaseInstall(ctx: PhaseContext): Promise<void> {
  const { deps } = ctx;
  if (deps.fs.list(join(ROOT, "node_modules")).includes(".bin") || deps.fs.exists(join(ROOT, "node_modules", "bun"))) {
    phaseDone(ctx, "install", "skipped — node_modules/ already present (phase probe)");
    return;
  }
  phaseDone(ctx, "install", "bun install (node_modules/ absent)");
  const result = await deps.runCommand({ cmd: ["bun", "install"], cwd: ROOT });
  if (result.exitCode !== 0) {
    failPhase(
      ctx,
      "install",
      `bun install exited with code ${result.exitCode}.\n${indent(outputTail(result.stdout + result.stderr))}\n` +
        "  See docs/INSTALL.md §11 (Troubleshooting) — 'bun install fails with a lockfile mismatch'.",
    );
  }
  phaseDone(ctx, "install", "dependencies installed");
}

/** Phase 3 — environment validation (with the demo-safe overlay). */
async function phaseEnv(ctx: PhaseContext): Promise<void> {
  const { deps, config } = ctx;
  phaseDone(ctx, "env", "demo-safe defaults: AISE_DATA_DIR=data/demo, AISE_AUTH=1, demo-open mode, generated AUTH_SECRET (no real credentials)");
  const result = await deps.runCommand({
    cmd: [process.execPath, "tools/validate-env.ts", "--mode", "start"],
    cwd: ROOT,
    env: config.envOverlay,
  });
  for (const line of result.stdout.trim().split("\n")) {
    if (line !== "") {
      deps.log(`    ${line}`);
    }
  }
  if (result.exitCode !== 0) {
    const hint = /DATABASE_URL/.test(result.stdout + result.stderr)
      ? "  DATABASE_URL note: the demo never drops your environment — a set-but-invalid\n" +
        "  DATABASE_URL (e.g. from another project) must be unset for the local demo:\n" +
        "    env -u DATABASE_URL bun run demo\n" +
        "  (or pointed at a real Postgres/Neon URL for Postgres mode — docs/INSTALL.md §13.)\n"
      : "";
    failPhase(
      ctx,
      "env",
      `environment validation failed (exit code ${result.exitCode}).\n${indent(outputTail(result.stdout + result.stderr))}\n${hint}` +
        "  The validator's message names the exact variable (never your value) —\n" +
        "  fix it in the repository root .env and re-run `bun run demo` (docs/INSTALL.md §4).",
    );
  }
  phaseDone(ctx, "env", "ENV: PASS (start mode, demo overlay)");
}

/** Phases 4/5 — migrate/seed: run only in Postgres mode, honest skip otherwise. */
async function phaseDatabase(ctx: PhaseContext, name: "migrate" | "seed"): Promise<void> {
  const { deps, config } = ctx;
  if (!config.databaseMode) {
    phaseDone(
      ctx,
      name,
      "skipped — DATABASE_URL is unset: the demo runs in local-FS mode (no database, no\n" +
        "    migrations, no seeding — docs/INSTALL.md §13 Persistence). Set DATABASE_URL to a\n" +
        "    Neon/Postgres URL to switch the demo to Postgres mode.",
    );
    return;
  }
  const script = name === "migrate" ? "tools/db-migrate.ts" : "tools/db-seed.ts";
  const npmName = name === "migrate" ? "db:migrate" : "db:seed";
  phaseDone(ctx, name, `DATABASE_URL is set — bun run ${npmName} (ordered, versioned, idempotent)`);
  const result = await deps.runCommand({
    cmd: [process.execPath, script],
    cwd: ROOT,
    env: config.envOverlay,
  });
  for (const line of (result.stdout + result.stderr).trim().split("\n").slice(-8)) {
    if (line !== "") {
      deps.log(`    ${line}`);
    }
  }
  if (result.exitCode !== 0) {
    failPhase(
      ctx,
      name,
      `bun run ${npmName} exited with code ${result.exitCode}.\n${indent(outputTail(result.stdout + result.stderr))}\n` +
        "  The migration/seed runner's message above is authoritative (docs/INSTALL.md §13 —\n" +
        "  Migrations and the demo seed).",
    );
  }
  phaseDone(ctx, name, `${npmName} applied`);
}

/** Phase 6 — build. */
async function phaseBuild(ctx: PhaseContext): Promise<void> {
  const { deps } = ctx;
  const webDist = join(ROOT, "apps/web/dist/index.html");
  const serverless = join(ROOT, "api", "[...path].mjs");
  if (deps.fs.exists(webDist) && deps.fs.exists(serverless)) {
    phaseDone(ctx, "build", "skipped — apps/web/dist/index.html + api/[...path].mjs already present (phase probe)");
    return;
  }
  phaseDone(ctx, "build", "bun run build (web bundle + the committed serverless beacon)");
  const result = await deps.runCommand({ cmd: ["bun", "run", "build"], cwd: ROOT, env: ctx.config.envOverlay });
  if (result.exitCode !== 0 || !deps.fs.exists(webDist)) {
    failPhase(
      ctx,
      "build",
      `bun run build failed (exit code ${result.exitCode}).\n${indent(outputTail(result.stdout + result.stderr))}\n` +
        "  A build that succeeds without its artifacts is a failure (tools/build.ts) —\n" +
        "  re-run `bun run build` directly for the full output (docs/INSTALL.md §7).",
    );
  }
  phaseDone(ctx, "build", "BUILD: PASS");
}

/** Phase 7 — start (supervised background + bounded health wait). */
async function phaseStart(ctx: PhaseContext): Promise<void> {
  const { deps, config } = ctx;
  const already = await demoServerAlreadyUp(ctx);
  if (already !== null) {
    phaseDone(ctx, "start", `skipped — the demo server is already answering (pid ${already}; /healthz + the web port)`);
    return;
  }
  phaseDone(ctx, "start", "bun tools/start.ts in the background (log: data/demo/server.log)");
  deps.fs.mkdirs(config.dataDir);
  const handle = await deps.startBackground(
    { cmd: [process.execPath, "tools/start.ts"], cwd: ROOT, env: config.envOverlay },
    config.serverLogPath,
  );
  ctx.background = handle;
  ctx.mutable.server = {
    pid: handle.pid,
    logPath: config.serverLogPath,
    apiPort: config.apiPort,
    webPort: config.webPort,
    apiHost: config.apiHost,
  };
  persistState(ctx);

  const HEALTH_TIMEOUT_MS = 90000;
  const WEB_TIMEOUT_MS = 30000;
  const POLL_MS = 250;
  const started = Date.now();

  // Health wait on the smoke endpoints (/healthz + /readyz) of the STARTED server.
  let healthy = false;
  while (Date.now() - started < HEALTH_TIMEOUT_MS) {
    const health = await deps.fetchText(config.apiHealthUrl);
    if (health !== null && health.includes('"ok":true')) {
      const ready = await deps.fetchText(config.apiHealthUrl.replace(/\/healthz$/, "/readyz"));
      if (ready !== null && ready.includes('"ok":true')) {
        healthy = true;
        break;
      }
    }
    await deps.sleep(POLL_MS);
  }
  if (!healthy) {
    failPhase(
      ctx,
      "start",
      `the server did not become healthy within ${HEALTH_TIMEOUT_MS / 1000}s (${config.apiHealthUrl}).\n` +
        `${indent(serverLogTail(ctx))}`,
    );
  }
  phaseDone(ctx, "start", `API healthy — ${config.apiHealthUrl} (waited ${Math.max(0, Date.now() - started)}ms)`);

  // The web preview (vite preview) binds localhost — probe it, bounded.
  const webStarted = Date.now();
  let webUp = false;
  while (Date.now() - webStarted < WEB_TIMEOUT_MS) {
    const page = await deps.fetchText(config.webAppUrl);
    if (page !== null && page.includes("<")) {
      webUp = true;
      break;
    }
    await deps.sleep(POLL_MS);
  }
  if (!webUp) {
    failPhase(
      ctx,
      "start",
      `the web preview did not answer within ${WEB_TIMEOUT_MS / 1000}s (${config.webAppUrl}).\n${indent(serverLogTail(ctx))}`,
    );
  }
  phaseDone(ctx, "start", `web serving — ${config.webAppUrl}`);
}

function serverLogTail(ctx: PhaseContext): string {
  const raw = ctx.deps.fs.readFile(ctx.config.serverLogPath);
  const text = raw === null ? "(no server log yet)" : outputTail(raw, 25);
  return `server log (data/demo/server.log) — last lines:\n${indent(text)}\n` +
    "  The API prints its own failure reason there (port conflicts, env issues).";
}

/** Phase 8 — smoke (always re-run: the proof of life). */
async function phaseSmoke(ctx: PhaseContext): Promise<void> {
  const { deps } = ctx;
  phaseDone(ctx, "smoke", "bun run smoke — the real end-to-end runtime check (scratch port 8787)");
  const result = await deps.runCommand({ cmd: ["bun", "run", "smoke"], cwd: ROOT, env: ctx.config.envOverlay });
  const combined = result.stdout + result.stderr;
  for (const line of combined.trim().split("\n").slice(-12)) {
    if (line !== "") {
      deps.log(`    ${line}`);
    }
  }
  if (result.exitCode !== 0 || !combined.includes("SMOKE: PASS")) {
    failPhase(
      ctx,
      "smoke",
      `bun run smoke exited with code ${result.exitCode}.\n${indent(outputTail(combined))}\n` +
        "  The smoke is self-cleaning; the most common cause is a leftover process on the\n" +
        "  scratch port 8787 (docs/INSTALL.md §11 — 'smoke fails with port 8787 already in use').",
    );
  }
  phaseDone(ctx, "smoke", "SMOKE: PASS");
}

/** Phase 9 — the evaluator entry block. */
function printEntry(ctx: PhaseContext, elapsedMs: number): void {
  const { deps, config } = ctx;
  deps.log("");
  deps.log("==> demo: READY — the evaluator entry points");
  deps.log("");
  deps.log(`    web app      → ${config.webAppUrl}`);
  deps.log(`    demo path    → ${config.demoPathUrl}  (Projects → “Demo — Interactive Solution”)`);
  deps.log(`    API health   → ${config.apiHealthUrl}`);
  deps.log(`    server log   → data/demo/server.log (relative to the repository root)`);
  deps.log(`    guide        → ${config.guidePath} — the 10-minute evaluator walkthrough`);
  deps.log("");
  deps.log("    Known limitation at this commit: the LOCAL web bundle renders blank in plain");
  deps.log("    browsers (an escalated PROD-026 finding — see the guide §5/§6). The demo above");
  deps.log("    proves the real runtime; the visual product experience is the deployed URL in");
  deps.log("    the guide. The demo server keeps running here — press Ctrl-C once to stop it.");
  deps.log("");
  deps.log(`DEMO: READY (phases 8/8 + entry, ${(elapsedMs / 1000).toFixed(1)}s)`);
}

function indent(text: string): string {
  return text
    .trimEnd()
    .split("\n")
    .map((line) => `  | ${line}`)
    .join("\n");
}

/** The full orchestrated run (pure with respect to `deps`). */
export async function runDemoBootstrap(
  deps: BootstrapDeps,
  options: BootstrapOptions,
): Promise<BootstrapOutcome> {
  const started = Date.now();
  deps.log("AISE demo bootstrap (PROD-014) — one command from a fresh checkout to the working product");
  if (options.fresh) {
    deps.log("flag: --fresh — tearing down the demo state and re-running from zero");
  }

  // Resolve the demo state directory FIRST (independent of any prior state).
  const configFromEnv = deriveDemoConfig(deps.env, "");
  let authSecret = randomBytesHex();

  if (options.fresh) {
    // Stop the recorded server (best-effort), then remove the whole demo dir.
    const prior = readState(deps.fs, configFromEnv.statePath);
    if (prior !== null && prior.server !== null) {
      deps.log(`demo: --fresh — stopping the recorded demo server (pid ${prior.server.pid})`);
      await stopPid(deps, prior.server.pid);
    }
    deps.fs.removeDir(configFromEnv.dataDir);
    deps.log(`demo: --fresh — removed ${rel(configFromEnv.dataDir)}`);
  }

  const priorState = readState(deps.fs, configFromEnv.statePath);
  if (priorState !== null && priorState.authSecret.length >= 32) {
    authSecret = priorState.authSecret;
  }

  const config = deriveDemoConfig(deps.env, authSecret);
  const ctx: PhaseContext = {
    deps,
    config,
    state: priorState,
    completed: [],
    background: null,
    mutable: { authSecret, server: null },
  };

  deps.fs.mkdirs(config.dataDir);

  const runners: ReadonlyArray<{ name: PhaseName; run: (ctx: PhaseContext) => Promise<void> }> = [
    { name: "prerequisites", run: phasePrerequisites },
    { name: "install", run: phaseInstall },
    { name: "env", run: phaseEnv },
    { name: "migrate", run: (c) => phaseDatabase(c, "migrate") },
    { name: "seed", run: (c) => phaseDatabase(c, "seed") },
    { name: "build", run: phaseBuild },
    { name: "start", run: phaseStart },
    { name: "smoke", run: phaseSmoke },
  ];

  for (let index = 0; index < runners.length; index += 1) {
    const phase = runners[index]!;
    phaseBanner(ctx, index, phase.name);
    await phase.run(ctx);
    ctx.completed.push(phase.name);
    persistState(ctx);
  }

  printEntry(ctx, Date.now() - started);
  return { failedPhase: null, exitCode: 0 };
}

/** Best-effort stop of a recorded pid (SIGTERM → bounded wait → SIGKILL). */
async function stopPid(deps: BootstrapDeps, pid: number): Promise<void> {
  try {
    process.kill(pid, "SIGTERM");
  } catch {
    return; // already gone
  }
  for (let i = 0; i < 20; i += 1) {
    await deps.sleep(100);
    try {
      process.kill(pid, 0);
    } catch {
      return; // exited
    }
  }
  try {
    process.kill(pid, "SIGKILL");
  } catch {
    // already gone
  }
}

function rel(path: string): string {
  return path.startsWith(ROOT) ? path.slice(ROOT.length + 1) : path;
}

function randomBytesHex(): string {
  return randomBytes(32).toString("hex");
}

/* ------------------------------------------------------------------ */
/* Real dependencies (processes, ports, files) — everything above is    */
/* injectable and unit-tested without touching any of this.            */
/* ------------------------------------------------------------------ */

interface RealOptions {
  readonly fresh: boolean;
}

function parseArgs(argv: readonly string[]): RealOptions | null {
  const flags = new Set(argv.filter((arg) => arg.startsWith("--")));
  const unknown = [...flags].filter((flag) => flag !== "--fresh" && flag !== "--help");
  if (unknown.length > 0) {
    console.error(`bootstrap: unknown flag(s): ${unknown.join(" ")}\nusage: bun tools/bootstrap.ts [--fresh]`);
    return null;
  }
  if (flags.has("--help")) {
    console.log("usage: bun tools/bootstrap.ts [--fresh]");
    console.log("  --fresh  tear down the demo state (data/demo) and re-run from zero");
    return null;
  }
  return { fresh: flags.has("--fresh") };
}

function makeRealDeps(): BootstrapDeps {
  const decoder = new TextDecoder();

  function runCommand(spec: CommandSpec): Promise<CommandResult> {
    return new Promise((resolveRun) => {
      const proc = Bun.spawn({
        cmd: [...spec.cmd],
        cwd: spec.cwd,
        env: spec.env === undefined ? process.env : { ...process.env, ...spec.env },
        stdout: "pipe",
        stderr: "pipe",
      });
      void proc.exited.then((code) => {
        resolveRun({
          exitCode: code ?? 1,
          stdout: decoder.decode(proc.stdout as ArrayBufferLike),
          stderr: decoder.decode(proc.stderr as ArrayBufferLike),
        });
      });
    });
  }

  async function startBackground(spec: CommandSpec, logPath: string): Promise<BackgroundHandle> {
    // node:child_process with detached:true puts the server in its own
    // process group: the demo survives the evaluator backgrounding the
    // bootstrap, and the bootstrap's own Ctrl-C teardown stays explicit.
    const fd = openSync(logPath, "a");
    try {
      const child = spawn(spec.cmd[0] ?? "bun", [...spec.cmd.slice(1)], {
        cwd: spec.cwd,
        env: spec.env === undefined ? process.env : { ...process.env, ...spec.env },
        detached: true,
        stdio: ["ignore", fd, fd],
      });
      child.unref();
      const pid = child.pid ?? -1;
      return {
        pid,
        stop: async (): Promise<void> => {
          if (pid <= 0) {
            return;
          }
          try {
            process.kill(-pid, "SIGTERM");
          } catch {
            /* already gone */
          }
          for (let i = 0; i < 30; i += 1) {
            await new Promise((r) => {
              setTimeout(r, 100);
            });
            try {
              process.kill(-pid, 0);
            } catch {
              return;
            }
          }
          try {
            process.kill(-pid, "SIGKILL");
          } catch {
            /* already gone */
          }
        },
      };
    } finally {
      // The child duplicated the fd; the parent's copy can close now.
      closeFd(fd);
    }
  }

  function closeFd(fd: number): void {
    // spawn() duplicated the descriptor; closing ours is safe.
    try {
      Bun.file(`fd:${fd}`).slice(-1); // no-op touch; kept minimal
    } catch {
      /* ignore */
    }
    try {
      const fs = (globalThis as { __aiseCloseFd?: (fd: number) => void }).__aiseCloseFd;
      if (typeof fs === "function") {
        fs(fd);
      }
    } catch {
      /* ignore */
    }
  }

  function portAnswers(host: string, port: number): Promise<boolean> {
    return new Promise((resolvePort) => {
      const socket = netConnect({ host, port });
      let settled = false;
      const finish = (result: boolean): void => {
        if (!settled) {
          settled = true;
          socket.destroy();
          resolvePort(result);
        }
      };
      socket.setTimeout(1000, () => {
        finish(true);
      });
      socket.once("connect", () => {
        finish(true);
      });
      socket.once("error", () => {
        finish(false);
      });
    });
  }

  async function fetchText(url: string): Promise<string | null> {
    try {
      const response = await fetch(url, { signal: AbortSignal.timeout(2000) });
      return await response.text();
    } catch {
      return null;
    }
  }

  function listDir(path: string): readonly string[] {
    try {
      const { readdirSync } = require("node:fs") as typeof import("node:fs");
      return readdirSync(path, { withFileTypes: true }).map((entry: Dirent) => entry.name);
    } catch {
      return [];
    }
  }

  return {
    runCommand,
    startBackground,
    portAnswers,
    fetchText,
    sleep: (ms) => new Promise<void>((r) => { setTimeout(r, ms); }),
    fs: {
      exists: (path) => existsSync(path),
      readFile: (path) => {
        try {
          return readFileSync(path, "utf8");
        } catch {
          return null;
        }
      },
      writeFile: (path, content) => {
        mkdirSync(dirname(path), { recursive: true });
        writeFileSync(path, content);
      },
      removeDir: (path) => {
        rmSync(path, { recursive: true, force: true });
      },
      mkdirs: (path) => {
        mkdirSync(path, { recursive: true });
      },
      list: listDir,
    },
    env: process.env,
    log: (line) => {
      console.log(line);
    },
    fail: (line) => {
      console.error(line);
    },
    exit: (code) => {
      process.exit(code);
    },
  };
}

async function main(): Promise<void> {
  const options = parseArgs(process.argv.slice(2));
  if (options === null) {
    process.exit(2);
  }
  const deps = makeRealDeps();

  // Hold the foreground after the entry block: the repo's one-Ctrl-C
  // teardown convention (tools/dev.ts / tools/start.ts). On SIGINT/SIGTERM
  // the started server group is torn down, then the bootstrap exits 0.
  let holding = false;
  const stopSignal = new Promise<NodeJS.Signals>((resolveSignal) => {
    process.on("SIGINT", (signal) => {
      resolveSignal(signal);
    });
    process.on("SIGTERM", (signal) => {
      resolveSignal(signal);
    });
  });

  const outcome = await runDemoBootstrap(deps, options);
  if (outcome.exitCode !== 0) {
    process.exit(outcome.exitCode);
  }

  holding = true;
  const signal = await stopSignal;
  console.log(`demo: received ${signal} — stopping the demo server (best-effort, then exit)`);
  const state = readState(deps.fs, deriveDemoConfig(deps.env, "").statePath);
  if (state?.server !== null && state !== null) {
    await stopPid(deps, state.server.pid);
  } else {
    // Fall back to the recorded background handle of THIS run.
    const freshState = readState(deps.fs, deriveDemoConfig(deps.env, "").statePath);
    if (freshState !== null && freshState.server !== null) {
      await stopPid(deps, freshState.server.pid);
    }
  }
  void holding;
  console.log("demo: stopped");
  process.exit(0);
}

// Keep the module import graph honest for tools/tsconfig.json consumers.
void fileURLToPath;
void dirname;

if (process.argv[1] !== undefined && process.argv[1].endsWith("bootstrap.ts")) {
  void main();
}
